%[text] # Lab 1 System Identification Prototype
%[text] This script demonstrates how to process the records from the step response experiments to identify the linear model parameters.
%[text] ## Load the Data
%[text] We start with the raw data.  In this case the data is contains just the fields we need from the larger raw data fiel.
clear;
load("step_resp_example.BIN.proc.mat");
%%
%[text] ## Create a single step response
%[text] To make this a bit general, we'll select just one set of input and output and give it general names so that we can more easily reuse the code.
in_t = dd.RCOU_timestamp;
in_y = dd.RCOU_C3;
out_t = dd.GPS_timestamp;
out_y = dd.GPS_Spd;
%[text] The above is for the speed response, for the yaw-rate response you will want to use these channels:
% in_t = dd.RCOU_timestamp;
% in_y = dd.RCOU_C1;
% out_t = dd.IMU_timestamp;
% out_y = dd.IMU_GyrZ;
%[text] Now plot
figure(1); %[output:429543e4]
clf; %[output:429543e4]
ax1=subplot(211); %[output:429543e4]
plot(in_t, in_y, 'b-') %[output:429543e4]
ylabel('Input (PWM)'); %[output:429543e4]
title('Step Response'); %[output:429543e4]
grid on; %[output:429543e4]
ax2 = subplot(212); %[output:429543e4]
plot(out_t, out_y, 'r-'); %[output:429543e4]
ylabel("Output (units)") %[output:429543e4]
xlabel('Time (s)'); %[output:429543e4]
grid on; %[output:429543e4]
linkaxes([ax1, ax2], 'x');  %[output:429543e4]
%%
%[text] ## Modify the timestamps
%[text] The raw timestamps are [unix times](https://www.unixtimestamp.com/) in elapsed seconds since 1 January 1970 UTC.  We will convert these by
%[text] 1. Assume that the experiment was run on a single day (UTC)
%[text] 2. Find the day and add this to the title of the figure as a date text string
%[text] 3. Convert the timestamps to a new timestamp in elapsed seconds since the start of the current day.
%[text] 4. Replot both curves with the new timestamps. \
% 1-2. Find the calendar date from the first timestamp
t_day_start = dateshift(datetime(in_t(1), 'ConvertFrom', 'posixtime', 'TimeZone', 'UTC'), 'start', 'day');
date_str = string(t_day_start, 'yyyy-MM-dd');

% 3. Convert timestamps to elapsed seconds since start of day
t_day_start_unix = posixtime(t_day_start);
in_t_day  = in_t  - t_day_start_unix;
out_t_day = out_t - t_day_start_unix;

% 4. Replot with new timestamps
figure(1);
clf; %[output:5ca9b0fd]
ax1 = subplot(211); %[output:5ca9b0fd]
plot(in_t_day, in_y, 'b-') %[output:5ca9b0fd]
ylabel('Input (PWM)'); %[output:5ca9b0fd]
title(sprintf('Step Response — %s (UTC)', date_str)); %[output:5ca9b0fd]
grid on; %[output:5ca9b0fd]
ax2 = subplot(212); %[output:5ca9b0fd]
plot(out_t_day, out_y, 'r-'); %[output:5ca9b0fd]
ylabel('Output (m/s)'); %[output:5ca9b0fd]
xlabel('Elapsed time since midnight UTC (s)'); %[output:5ca9b0fd]
grid on; %[output:5ca9b0fd]
linkaxes([ax1, ax2], 'x'); %[output:5ca9b0fd]
%%
%[text] ## Isolate a single step response
%[text] Using the graph, select start and stop times to isolate a single step response we can use for system identification.  This process is manual and uses MATLAB's figure tools.
%[text] One way to do this is...
%[text] - Open the figure in a separate window
%[text] - Use the zoom and data tips graphical tools to select three points: start, time zero (when the step input begins) and end. \
tstart = 80121;
t0 = 80122.9;
tend = 80135.2;
%[text] Annotate the original plot to double check by adding markers to both timeseries plots to show the three points.
figure(1);
axes(ax1); hold on; %[output:2180a1e7]
xline(tstart, 'g--', 'tstart', 'LabelVerticalAlignment', 'bottom'); %[output:2180a1e7]
xline(t0,     'k-',  't_0',    'LabelVerticalAlignment', 'bottom'); %[output:2180a1e7]
xline(tend,   'r--', 'tend',   'LabelVerticalAlignment', 'bottom'); %[output:2180a1e7]
axes(ax2); hold on; %[output:2180a1e7]
xline(tstart, 'g--', 'tstart', 'LabelVerticalAlignment', 'bottom'); %[output:2180a1e7]
xline(t0,     'k-',  't_0',    'LabelVerticalAlignment', 'bottom'); %[output:2180a1e7]
xline(tend,   'r--', 'tend',   'LabelVerticalAlignment', 'bottom'); %[output:2180a1e7]
dt = 2.0;
xlim(ax2,[tstart-dt, tend+dt]) %[output:2180a1e7]
%%
%[text] ## Plot the isolated step response
%[text] Shift time so $t=0$ corresponds to `t0` (when the step begins), then extract the window and replot.
in_mask  = in_t_day  >= tstart & in_t_day  <= tend;
out_mask = out_t_day >= tstart & out_t_day <= tend;

in_t_step  = in_t_day(in_mask)  - t0;
in_y_step  = in_y(in_mask);
out_t_step = out_t_day(out_mask) - t0;
out_y_step = out_y(out_mask);

figure(2); clf; %[output:032bb857]
ax3 = subplot(211); %[output:032bb857]
plot(in_t_step, in_y_step, 'b-'); %[output:032bb857]
ylabel('Input (PWM)'); %[output:032bb857]
title(sprintf('Isolated Step Response — %s (UTC)', date_str)); %[output:032bb857]
grid on; %[output:032bb857]
ax4 = subplot(212); %[output:032bb857]
plot(out_t_step, out_y_step, 'r-', "DisplayName","Exp"); %[output:032bb857]
ylabel('Output (m/s)'); %[output:032bb857]
xlabel('Time relative to step (s)'); %[output:032bb857]
grid on; %[output:032bb857]
linkaxes([ax3, ax4], 'x'); %[output:032bb857]
%%
%[text] ## Scale the input to percentage
%[text] The input is in units of PWM, but because the ArduPilot works in units of percent effort, we need to scale the input based on the configured PWM limits from the ArduPilot configuration parameters.  For throttle (RC channel 3) and steering (RC channel 1) the values are .params file are
%[text] ```
%[text] RC3_MAX,1910
%[text] RC3_MIN,1109
%[text] RC1_MAX,1900
%[text] RC1_MIN,1100
%[text] ```
inzero = 1500;
inmax = 1910;
inmin = 1109;
%[text] Convert the PWM input to normalized effort (±1) and update the isolated step response plot.
in_y_norm = zeros(size(in_y_step));
pos = in_y_step >= inzero;
in_y_norm( pos) = (in_y_step( pos) - inzero) / (inmax - inzero);
in_y_norm(~pos) = (in_y_step(~pos) - inzero) / (inzero - inmin);

figure(2);
axes(ax3); %[output:528768cd]
cla; %[output:656af38a]
plot(in_t_step, in_y_norm, 'b-'); %[output:656af38a]
ylabel('Input (norm., ±1)'); %[output:656af38a]
grid on %[output:656af38a]
%%
%[text] ## Estimate first-order response model parameters.
%[text] The generic first-order model is
%[text] $G(s) = \\frac{K\_{DC}}{\\tau \\, s +1}$
%[text] By inspecting the graphs we can come up with a **rough estimate** of the model parameters.  This is done just by eye as a starting point for a model fit. 
%[text] From the steady state values we can estimate the DC gain.
in_ss = 0.188;  % Fraction 
out_ss = 1.25;  % m/s
Kdc_est = out_ss/in_ss %[output:2b9e342f]
%[text] From the output graph, we can estimate the time constant.  A coarse estimate is fine here. 
tau_est = 0.75; %s
%[text] And overlay the response from our estimated transfer function model.  The step response, in the time domain, is
%[text] $y(t) = A\_{\\text{step}} \\, K\_{DC} \\, \\left( 1- e^{-t/\\tau}\\right)$
%[text] where $A\_{\\text{step}}$ is the amplitude of the step input.
%[text] **Note: It is critical that we record the amplitude of the step input used.  This was done above when determining our estimate of Kdc.**
Astep = in_ss;
%[text] We want to just have the input times greater than zero.
tmask = out_t_step  >= 0;
tt = out_t_step(tmask);
%[text] Now generate the estimated response
yy_est = Astep * Kdc_est * (1 - exp(-tt/tau_est));
%[text] And overlay
figure(2);
axes(ax4); %[output:86469b49]
hold on %[output:86469b49]
plot(tt,yy_est,'g:',"DisplayName","Intial Est") %[output:86469b49]
legend("Location","southeast") %[output:86469b49]
%%
%[text] ## Refine the model parameters with a curve fit
%[text] We'll use the lsqcurvefit solver from the Optimization Toolbox (install if needed).
%[text] Write a function that generates the timeseries for the step input.
function y = first_order_step(params, t, Astep)
    Kdc = params(1);
    tau = params(2);
    y = Astep * Kdc * (1 - exp(-t / tau));
end
%[text] Initial guess at the params vector
params0 = [Kdc_est, tau_est];
%[text] Trim the experiment data for just the positive values
tmask = out_t_step  >= 0;
tt = out_t_step(tmask);
yy = out_y_step(tmask);
%[text] Call the solver using an anonymous function to pass the Astep variable.
params_fit = lsqcurvefit(... %[output:group:84b2feab] %[output:92519fe9]
    @(p,t) first_order_step(p, t, Astep), ... %[output:92519fe9]
    params0, tt, yy); %[output:group:84b2feab] %[output:92519fe9]
K_fit = params_fit(1) %[output:6e6ef907]
tau_fit = params_fit(2) %[output:86fe91e7]
%[text] Overlay the new model
y_fit = first_order_step([K_fit, tau_fit], tt, Astep);
figure(2);
axes(ax4); %[output:379ca0fc]
hold on %[output:379ca0fc]
plot(tt,y_fit,'k--',"DisplayName","Fit") %[output:379ca0fc]
legend("Location","southeast") %[output:379ca0fc]
%[text] Now we have a model with parameters chosen so that the time response approximates the experiment data.
%[text] $G^\*(s) = \\frac{ \\text{K\\\_fit} } { \\text{tau\\\_fit  \\,  s + 1} }= \\frac{6.6}{1.1 s +1}\n$
%[text] Note that we don't address any quantitative measures of goodness-of-fit.   This is done in the interest of time and scope. 
%[text] 

